record.field:
bot = env.ref('base.user_root')
ProductTemplate = env['product.template'].sudo().with_user(bot)
ProductAttribute = env['product.attribute'].sudo().with_user(bot)
ProductAttributeValue = env['product.attribute.value'].sudo().with_user(bot)
StockQuant = env['stock.quant'].sudo().with_user(bot)

result = []

for p in args.products():
    # Extract the Odoo ID from the input
    pid = p.get('oid')
    external_id = p.get('id')
    stock_available = p.pop('stock_available') or []
    total_stock = sum(item.get('stock') for item in stock_available)
    gallery_images_data = p.pop('image_ids', [])
    attribute_variants = []
    template = ProductTemplate.search([('id', '=', external_id)], limit=1)

    # Skip if product already exists in the external system with same external ID
    if external_id and template.exists():
        # Product already exists in the external system
        variants = template.product_variant_ids

        # Handle single variant products differently
        if len(variants) == 1:
            result.append((pid, external_id, variants[0].id))
            continue

        # Initialize attribute type groups (only for multi-variant products)
        attribute_type_groups = {}

        # Collect attribute variants information
        for variant in variants:
            for attr_value in variant.product_template_attribute_value_ids:
                attr_name = attr_value.attribute_id.name

                # Initialize the attribute type group if it doesn't exist
                if attr_name not in attribute_type_groups:
                    attribute_type_groups[attr_name] = {
                        'name': attr_name,
                        'attributes': {}  # Use dict to avoid duplicates
                    }

                # Add the value to the attribute group
                value_name = attr_value.name
                if value_name not in attribute_type_groups[attr_name]['attributes']:
                    attribute_type_groups[attr_name]['attributes'][value_name] = {
                        'name': value_name,
                        'variant_ids': []
                    }

                # Add variant ID if not already present
                if variant.id not in attribute_type_groups[attr_name]['attributes'][value_name]['variant_ids']:
                    attribute_type_groups[attr_name]['attributes'][value_name]['variant_ids'].append(variant.id)

        # Convert the attribute groups to the final format
        attribute_variants = []
        for attr_type, attr_data in attribute_type_groups.items():
            attribute_variants.append({
                'name': attr_type,
                'attributes': list(attr_data['attributes'].values())
            })

        result.append((pid, external_id, attribute_variants))
        continue

    # Check if we already have a product with the same Odoo ID in our database
    # We need to use a different approach since rpc_external_id doesn't exist in the remote system
    # The external system might be storing the Odoo ID in a custom field or we could check by name/SKU

    # Check by name and default_code (SKU) as an alternative to rpc_external_id
    existing_product = False
    if p.get('default_code'):
        existing_product = ProductTemplate.search([('default_code', '=', p.get('default_code'))], limit=1)

    if not existing_product and p.get('name'):
        existing_product = ProductTemplate.search([('name', '=', p.get('name'))], limit=1)

    if existing_product:
        result.append((pid, existing_product.id))
        continue

    # Pop oid, we don't need it for creation
    p.pop('oid', None)  # Added None as default value to avoid KeyError

    # Extract attributes, main image, and gallery images from the input data
    attributes_data = p.pop('attributes', [])
    image_data = p.pop('image', False)

    # Handle type field change in v18: 'product' -> 'consu'
    if 'type' in p and p['type'] == 'product':
        p['type'] = 'consu'

    # Process main image data if provided
    if image_data:
        p['image_1920'] = image_data

    p.update({ 'is_published': total_stock > 0, 'is_storable': True })

    # Create the product without attributes and gallery images first
    product = ProductTemplate.create(p)

    # Now handle attributes if any
    for attr_data in attributes_data:
        # Find or create the attribute
        attribute = ProductAttribute.search([('name', '=', attr_data['name'])], limit=1)
        if not attribute:
            attribute = ProductAttribute.create({'name': attr_data['name']})

        # Find or create attribute values
        value_ids = []
        for val_data in attr_data.get('values', []):
            value = ProductAttributeValue.search([
                ('name', '=', val_data['name']),
                ('attribute_id', '=', attribute.id)
            ], limit=1)
            if not value:
                value = ProductAttributeValue.create({
                    'name': val_data['name'],
                    'attribute_id': attribute.id
                })
            value_ids.append(value.id)

        # Create attribute line
        if value_ids:
            product.write({
                'attribute_line_ids': [(0, 0, {
                    'attribute_id': attribute.id,
                    'value_ids': [(6, 0, value_ids)]
                })]
            })

    variants = product.product_variant_ids

    # Handle single variant products differently
    if len(variants) == 1:
        result.append((pid, product.id, variants[0].id))
        continue

    # Initialize attribute type groups (only for multi-variant products)
    attribute_type_groups = {}

    # Collect attribute variants information
    for variant in variants:
        for attr_value in variant.product_template_attribute_value_ids:
            attr_name = attr_value.attribute_id.name

            # Initialize the attribute type group if it doesn't exist
            if attr_name not in attribute_type_groups:
                attribute_type_groups[attr_name] = {
                    'name': attr_name,
                    'attributes': {}  # Use dict to avoid duplicates
                }

            # Add the value to the attribute group
            value_name = attr_value.name
            if value_name not in attribute_type_groups[attr_name]['attributes']:
                attribute_type_groups[attr_name]['attributes'][value_name] = {
                    'name': value_name,
                    'variant_ids': []
                }

            # Add variant ID if not already present
            if variant.id not in attribute_type_groups[attr_name]['attributes'][value_name]['variant_ids']:
                attribute_type_groups[attr_name]['attributes'][value_name]['variant_ids'].append(variant.id)

    # Convert the attribute groups to the final format
    attribute_variants = []
    for attr_type, attr_data in attribute_type_groups.items():
        attribute_variants.append({
            'name': attr_type,
            'attributes': list(attr_data['attributes'].values())
        })

    # Removing stock update code from here since it should only happen during image updates

    result.append((pid, product.id, attribute_variants))

log.debug('--------------------------------------------------')

ModelData = env['ir.model.data']

xml_id = args.ref()

if not xml_id or '.' not in xml_id:
    raise ValueError("External ID must be in format 'module.identifier'")

module, name = xml_id.split('.', 1)

res = ModelData.search([('module', '=', module), ('name', '=', name)])

if res:
    result = (res.res_id, res.model)
else:
    result = False

bot = env.ref('base.user_root')
ProductTemplate = env['product.template'].sudo().with_user(bot)
ProductProduct = env['product.product'].sudo().with_user(bot)
StockQuant = env['stock.quant'].sudo().with_user(bot)


result = []
stock_location = env.ref('stock.stock_location_stock')

for p in args.products():
    product_template = ProductTemplate.search([('id', '=', p.get('id'))], limit=1)

    # Skip if product already exists in the external system with same external ID
    if not product_template.exists():
        raise Exception(f"Product template not found: {p.get('id')}")

    # Get stock data if available
    stock_available = product_template.is_storable and p.get('stock_available', []) or []

    # Update stock for variants if stock data is provided
    for variant_stock in stock_available:
        pvariant = ProductProduct.browse([variant_stock.get('product_id')])

        if not pvariant.exists():
            raise Exception(f"Product variant not found: {variant_stock.get('product_id')}")

        # Update stock quantity
        quant = StockQuant.search([
            ('product_id', '=', pvariant.id),
            ('location_id', '=', stock_location.id)
        ], limit=1)

        if not quant:
            quant = StockQuant.create({
                'product_id': pvariant.id,
                'location_id': stock_location.id
            })

        quant.action_set_inventory_quantity()

        quant.write({
            'inventory_quantity_set': True,
            'inventory_quantity': variant_stock.get('stock', 0)
        })

        quant.action_apply_inventory()

    gallery_images_data = p.get('image_ids', {})  # Changed to dict default

    # Skip if no image data
    if not gallery_images_data:
        continue

    image_type = gallery_images_data.get('type')
    images = gallery_images_data.get('images', [])

    if image_type == 'template':
        product_images = []

        for idx, img_data in enumerate(images):
            # Ensure name is never empty - use product name with index if name is not provided
            image_name = img_data.get('name')
            if not image_name or not image_name.strip():
                image_name = f"{product_template.name} - Image {idx + 1}"

            image_data = {
                'name': image_name,
                'image_1920': img_data.get('image'),
                'sequence': img_data.get('sequence', 10),
                'product_tmpl_id': product_template.id
            }

            product_images.append((0, 0, image_data))

        log.debug(product_images)

        if product_images and not product_template.product_template_image_ids:
            product_template.write({'product_template_image_ids': product_images})

    elif image_type == 'variant':

        for var_data in images:

            variant = ProductProduct.search([('id', '=', var_data.get('variant_id'))], limit=1)

            if not variant.exists():
                raise Exception(f"Product variant not found: {var_data.get('variant_id')}")

            product_images = []

            for idx, img_data in enumerate(var_data['images']):
                image_name = img_data.get('name')
                if not image_name or not image_name.strip():
                    image_name = f"{variant.name} - Image {idx + 1}"

                image_data = {
                    'name': image_name,
                    'image_1920': img_data.get('image'),
                    'sequence': img_data.get('sequence', 10),
                    'product_variant_id': variant.id
                }

                product_images.append((0, 0, image_data))

            log.debug(product_images)

            if product_images and not variant.product_variant_image_ids:
                variant.write({'product_variant_image_ids': product_images})

result = True

log.debug('--------------------------------------------------')

bot = env.ref('base.user_root')
SaleOrder = env['sale.order'].sudo().with_user(bot)

order = SaleOrder.search([('id', '=', args.order_id())], limit=1)

if not order:
    raise Exception('Order not found')

order.write(args.carrier_data())

pickings = order.picking_ids.filtered(lambda p: p.picking_type_code == 'outgoing' and p.state == 'assigned')

result = False

if pickings:
    for company in pickings.company_id:
        if not company.has_received_warning_stock_sms:
            company.sudo().write({
                'has_received_warning_stock_sms': True,
                'stock_move_sms_validation': False,
            })

    result = pickings.button_validate()

